begin;
select no_plan();
insert into auth.users(id,email) values
 ('a6666666-1111-4111-8111-111111111101','receipt-owner@example.test'),
 ('a6666666-1111-4111-8111-111111111102','receipt-reader@example.test');
select set_config('request.jwt.claim.sub','a6666666-1111-4111-8111-111111111102',true);select public.complete_profile('Receipt reader');
select set_config('request.jwt.claim.sub','a6666666-1111-4111-8111-111111111101',true);select public.complete_profile('Receipt owner');
insert into public.groups(id,name,currency_code) values('a6666666-1111-4111-8111-111111111100','Receipts','AUD');
insert into public.group_members(group_id,user_id,display_name) values('a6666666-1111-4111-8111-111111111100','a6666666-1111-4111-8111-111111111102','Reader');
select set_config('test.receipt_expense',(public.create_expense('a6666666-1111-4111-8111-111111111100','Receipt test',101,now(),
 jsonb_build_array(jsonb_build_object('member_id',m.id,'amount_minor',101)),jsonb_build_array(jsonb_build_object('member_id',m.id,'amount_minor',101)),gen_random_uuid())).id::text,true)
 from public.group_members m where m.user_id=auth.uid();
set local role authenticated;
select lives_ok($$select public.reserve_expense_receipt('a6666666-1111-4111-8111-111111111110',current_setting('test.receipt_expense')::uuid,repeat('0',64),'image/png',100)$$,'authorized bounded intent');
select lives_ok($$select public.reserve_expense_receipt('a6666666-1111-4111-8111-111111111110',current_setting('test.receipt_expense')::uuid,repeat('0',64),'image/png',100)$$,'same intent replay');
select is((select count(*) from public.expense_receipts),1::bigint,'one upload identity');
select throws_ok($$select public.reserve_expense_receipt('a6666666-1111-4111-8111-111111111110',current_setting('test.receipt_expense')::uuid,repeat('1',64),'image/png',100)$$,'P0001','Receipt identity is unavailable','identity binds content digest');
select throws_ok($$select public.reserve_expense_receipt(gen_random_uuid(),current_setting('test.receipt_expense')::uuid,repeat('0',64),'image/svg+xml',100)$$,'P0001','Invalid receipt','active format rejected');
select throws_ok($$select public.reserve_expense_receipt(gen_random_uuid(),current_setting('test.receipt_expense')::uuid,repeat('0',64),'image/png',4194305)$$,'P0001','Invalid receipt','size bound enforced');
select throws_ok($$update public.expense_receipts set state='ready'$$,'42501',null,'metadata mutation denied');
select throws_ok($$delete from public.receipt_events$$,'42501',null,'audit deletion denied');
select throws_ok($$select public.finish_expense_receipt('a6666666-1111-4111-8111-111111111110',auth.uid(),false)$$,'42501',null,'caller cannot confirm unchecked bytes');
select set_config('request.jwt.claim.sub','a6666666-1111-4111-8111-111111111102',true);
select is(jsonb_array_length(public.get_expense_receipts(current_setting('test.receipt_expense')::uuid)->'receipts'),0,'another member cannot read pending upload');
select throws_ok($$select public.delete_expense_receipt('a6666666-1111-4111-8111-111111111110')$$,'P0001','Receipt deletion is unavailable','ordinary reader cannot delete uploader receipt');
reset role;
set local role service_role;
select lives_ok($$select public.finish_expense_receipt('a6666666-1111-4111-8111-111111111110','a6666666-1111-4111-8111-111111111101',false)$$,'trusted gateway owns completion');
select throws_ok($$select public.claim_stale_receipt('a6666666-1111-4111-8111-111111111110',now())$$,'P0001','Receipt is not stale','cleanup never claims ready receipt');
reset role;
set local role authenticated;
select is(jsonb_array_length(public.get_expense_receipts(current_setting('test.receipt_expense')::uuid)->'receipts'),1,'ready image shared with current members');
select set_config('request.jwt.claim.sub','a6666666-1111-4111-8111-111111111199',true);
select is((select count(*) from public.expense_receipts),0::bigint,'outsider metadata hidden by RLS');
select throws_ok($$select public.get_expense_receipts(current_setting('test.receipt_expense')::uuid)$$,'P0001','Expense is unavailable','outsider RPC denied');
select set_config('request.jwt.claim.sub','a6666666-1111-4111-8111-111111111101',true);
select public.reserve_expense_receipt('a6666666-1111-4111-8111-111111111111',current_setting('test.receipt_expense')::uuid,repeat('0',64),'image/png',100);
select public.archive_group('a6666666-1111-4111-8111-111111111100');
select is(public.get_expense_receipts(current_setting('test.receipt_expense')::uuid)->>'can_upload','false','archive read only');
select throws_ok($$select public.delete_expense_receipt('a6666666-1111-4111-8111-111111111110')$$,'P0001','Receipt deletion is unavailable','archive disallows delete');
select public.reopen_group('a6666666-1111-4111-8111-111111111100');
select public.void_expense(current_setting('test.receipt_expense')::uuid);
select is(public.get_expense_receipts(current_setting('test.receipt_expense')::uuid)->>'can_upload','false','void retains history without new uploads');
select public.delete_expense_receipt('a6666666-1111-4111-8111-111111111110');
select is((select state from public.expense_receipts where id='a6666666-1111-4111-8111-111111111110'),'deleting','delete intent revokes object reads first');
reset role;
update public.expense_receipts set updated_at=now()-interval '25 hours' where id='a6666666-1111-4111-8111-111111111111';
select set_config('test.stale_at',(select updated_at::text from public.expense_receipts where id='a6666666-1111-4111-8111-111111111111'),true);
set local role service_role;
select lives_ok($$select public.claim_stale_receipt('a6666666-1111-4111-8111-111111111111',current_setting('test.stale_at')::timestamptz)$$,'stale incomplete intent claimed with version guard');
select lives_ok($$select public.finish_expense_receipt('a6666666-1111-4111-8111-111111111110','a6666666-1111-4111-8111-111111111101',true)$$,'confirmed storage deletion completes metadata');
select lives_ok($$select public.finish_expense_receipt('a6666666-1111-4111-8111-111111111110','a6666666-1111-4111-8111-111111111101',true)$$,'deletion replay idempotent');
reset role;
select is((select count(*) from public.receipt_events where receipt_id='a6666666-1111-4111-8111-111111111110'),4::bigint,'reserved ready deleting deleted audit retained exactly once');
select is((select count(*) from public.expenses),1::bigint,'receipt lifecycle never creates ledger expenses');
select set_config('request.jwt.claim.sub','a6666666-1111-4111-8111-111111111101',true);
select public.archive_group('a6666666-1111-4111-8111-111111111100');
select lives_ok($$delete from auth.users where id='a6666666-1111-4111-8111-111111111101'$$,'settled archived deletion retains receipt audit');
select is((select count(*) from public.expense_receipts where created_by is null),2::bigint,'receipt creator deidentified');
select is((select count(*) from public.receipt_events where actor_id is not null),0::bigint,'actor identity deidentified');
select * from finish();
rollback;
